<!doctype html>
<html>

<head>
    <meta charset="utf-8">
    <style>
        @import url('http://fonts.googleapis.com/css2?family=Roboto:wght@100;300;400;500;700;900&display=swap');

        body {
            font-family: 'Roboto', sans-serif;
        }

        .f-left {
            float: left;
        }

        .f-right {
            float: right;
        }

        .t-right {
            text-align: right;
        }

        .t-center {
            text-align: center;
        }

        .t-left {
            text-align: left;
        }

        .logo-h {
            width: 100px;
        }

        .border {
            border: 1px solid #000;
            border-radius: 10px;
        }

        .full-width {
            padding: 15px;
            overflow: hidden;
        }

        .report p strong {
            font-size: 17px;
        }

        .report p {
            color: #000;
            margin: 0px;
            padding-top: 8px;
            font-size: 16px;
        }

        .report p a {
            color: #000;
        }

        .head-block {
            overflow: hidden;
            margin-bottom: 15px;
        }

        .full-width h4 {
            margin: 0px;
            color: #000;
            font-size: 20px;
        }

        .border-bottom {
            border-bottom: 1px solid #0000006e;
            overflow: hidden;
            padding-top: 15px;
            margin-bottom: 15px;
        }

        .vehicle-information .information-d {
            padding-top: 5px;
        }

        .vehicle-information ul {
            margin-top: 0px;
            padding-left: 15px;
        }

.vehicle-information ul li {
width: 41%;
float: left;
color: #000;
font-size: 24px;
display: block;
padding: 6px 33px 0px;
position: relative;
padding-left: 25px;
font-weight: 500;
}

		img.icon-logo {
		width: 25px;
		position: absolute;
		left: -5px;
		top: 8px;
		}

        .information-detail h3 {
            margin: 0px;
            color: #000;
            font-weight: 300;
            font-size: 22px;
        }

        .information-detail h5 {
            margin: 0px;
            color: #000;
            font-weight: 300;
            font-size: 35px;
        }

        .information-detail h1 {
            font-size: 40px;
            font-weight: bold;
            color: #000;
            margin: 0px;
        }

        .information-detail h1 sub {
            font-size: 20px;
            font-weight: 300;
        }

        .w-full {
            width: 100%;
        }

        .bottom-text {
            width: 100%;
            overflow: hidden;
            line-height: 15px;
        }

        .vehicle-information {
            overflow: hidden;
        }

        .text-right {
            text-align: right;
        }

        .one-third {
            width: 33.33%;
            float: left;
        }

strong.txtr {
background: #000;
float: right;
color: #fff;
padding: 16px 10px;
width: 250px;
text-align: center;
font-weight: 600;
min-height: 35px;
font-size: 24px;
}
    </style>
</head>

<body style="width:1140px;margin:50px auto;">
    <div class="report" style="border: 1px solid #000; padding: 10px;">
        <div class="head-block">
            <div class="report-header-left f-left" style="width:50%;">
                <!--<img src="{{LOGO}}" class="logo-h"/> -->
                <img src="{{LOGO}}" class="logo-main" style="width: 250px;display: inline-block;" /> &nbsp; &nbsp;
                <!--<img src="reset.png" class="logo-h" style="width:60px;position: relative;top: -20px;" /> -->
            </div>
            <div class="report-header-right f-right t-right" style="width:50%;">
                <p><strong>{{BNAME}}</strong></p>
                <p>{{BADDRESS}}, {{BCITY}}, {{BSTATE}} {{BCODE}}</p>
                <p>{{BPHONE}}&nbsp;&nbsp; </p>
            </div>
        </div>
        <div class="border full-width">
            <div class="report-header-left f-left" style="width:100%;">
                <div class="one-third">
                    <p><span class="vin">VIN: {{VIN}}</span> </p>
                </div>

                <div class="one-third">
                    <p><span class="stock"> Stock #: {{STOCK}}</span> </p>
                </div>

                <div class="one-third text-right">
                    <!-- <img src="scan-me.png" class="logo-h" style="width:60px;" /> -->
                    {{QR}}
                    <p> <span class="stock"> SCAN Me</span></p>

                </div>
            </div>

            <div class="border-bottom" style="width:100%;border: 0px;padding: 0px;margin: 0px;"></div>
            <div class="vehicle-information">
                <ul>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />
                        Body Type: <strong class="txtr">{{BODY}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />Doors: <strong class="txtr">{{DOOR}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />Engine: <strong class="txtr">{{ENGINE}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />Cylinder: <strong class="txtr">{{CYLINDER}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />Transmission: <strong class="txtr">{{TRANSMISSION}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />Drivetrain: <strong class="txtr">{{DRIVETRAIN}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />KM Traveled: <strong class="txtr"> {{ODOMETER}} {{KM_MILES}} </strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" />Passengers: <strong class="txtr">{{PASSENGERS}}</strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" /> CITY L/100: <strong class="txtr"> {{FUEL_CITY}} </strong>
                    </li>
                    <li>
                        <img src="data:image/png;base64,"
                            class="icon-logo" /> HWY L/100: <strong class="txtr"> {{FUEL_HWY}} </strong>
                    </li>
                </ul>
            </div>
            <!--<div class="vehicle-information">
                <p style="padding-top: 15px;"><strong>Vehicle Description</strong></p>
                <p>{{DESCRIPTION}}</p>                
            </div> -->
            <div class="border-bottom" style="width:100%;"></div>
            <div class="information-detail" style="min-height:220px;position: relative;">
                <div class="report-header-right f-left t-right information-detail"
                    style="width: 100%;position: absolute;top: 20%;right: 0px;">
                    <h2 style="font-size:20px;font-weight:bold;margin: 0px;text-align:center;">
                        <span style="font-size:100px;font-weight:bold;text-align:center;"> $ {{PRICE}} </span>
                    </h2>
                    <strong style="font-size:16px;padding-right: 15px;font-weight:300;"> + Doc Fee: $399 & Taxes</strong>
                </div>
            </div>
            <div class="border-bottom" style="width:100%;"></div>
            <div class="information-detail" style="min-height:250px;"> <p style="font-size: 20px;line-height: 28px;"> {{DESCRIPTION}} </p> </div>
        </div>
        <div class="bottom-text t-center">
            <p style="font-size:9px;">*Prices fo this vehicle may not include charges such as License; Registration
                Fees; Local Taxes; Finance Charges; or Delivery Fees. Every reasonable effort is made to ensure the
                accuracy of the information listed above. Vehicle pricing, incentives, options (including standard
                equipment), and technical specifications listed may not match the exact vehicle displayed. Please
                confirm with a sales representative the accuracy of this information.</p>
        </div>
    </div>
</body>

</html>